// packages/core/src/components/Dialog/Dialog.tsx
"use client";
import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../utils/cn";

export type DialogSize = "sm" | "md";
export type DialogSeverity = "default" | "danger";

interface DialogContextValue {
  isOpen: boolean;
  onClose?: () => void;
  size?: DialogSize;
  severity?: DialogSeverity;
}

const DialogContext = React.createContext<DialogContextValue>({
  isOpen: false,
});

const dialogPanelVariants = cva(
  "relative w-full overflow-hidden bg-background border border-border/80 shadow-2xl rounded-3xl p-6 sm:p-7 transition-all animate-in fade-in-0 zoom-in-95 duration-200 focus-visible:outline-none",
  {
    variants: {
      size: {
        sm: "max-w-sm",
        md: "max-w-lg",
      },
      severity: {
        default: "",
        danger: "border-t-4 border-t-destructive",
      },
    },
    defaultVariants: {
      size: "md",
      severity: "default",
    },
  }
);

export interface DialogProps {
  isOpen: boolean;
  onClose?: () => void;
  size?: DialogSize;
  severity?: DialogSeverity;
  isDismissable?: boolean;
  children: React.ReactNode;
}

const Dialog: React.FC<DialogProps> = ({
  isOpen,
  onClose,
  size = "md",
  severity = "default",
  isDismissable = true,
  children,
}) => {
  // ESC key to close
  React.useEffect(() => {
    if (!isOpen) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape" && isDismissable) {
        onClose?.();
      }
    };

    document.addEventListener("keydown", handleKeyDown);
    return () => {
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [isOpen, isDismissable, onClose]);

  // Prevent background scroll when dialog is open
  React.useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "";
    }
    return () => {
      document.body.style.overflow = "";
    };
  }, [isOpen]);

  if (!isOpen) return null;

  return (
    <DialogContext.Provider value={{ isOpen, onClose, size, severity }}>
      <div className="fixed inset-0 z-50 flex items-center justify-center p-4 sm:p-6">
        {/* Backdrop */}
        <div
          className="animate-in fade-in-0 bg-background/80 fixed inset-0 backdrop-blur-md transition-opacity duration-200"
          aria-hidden="true"
          onClick={() => {
            if (isDismissable) onClose?.();
          }}
        />

        {/* Dialog Centered Content */}
        <div className="pointer-events-auto relative z-10 flex w-full items-center justify-center">
          {children}
        </div>
      </div>
    </DialogContext.Provider>
  );
};
Dialog.displayName = "Dialog";

export interface DialogContentProps
  extends React.HTMLAttributes<HTMLDivElement>, VariantProps<typeof dialogPanelVariants> {}

const DialogContent = React.forwardRef<HTMLDivElement, DialogContentProps>(
  ({ className, size: propSize, severity: propSeverity, children, ...props }, ref) => {
    const context = React.useContext(DialogContext);
    const size = propSize ?? context.size ?? "md";
    const severity = propSeverity ?? context.severity ?? "default";

    return (
      <div
        ref={ref}
        role="dialog"
        aria-modal="true"
        className={cn(dialogPanelVariants({ size, severity }), className)}
        {...props}
      >
        {children}
      </div>
    );
  }
);
DialogContent.displayName = "DialogContent";

export interface DialogHeaderProps extends React.HTMLAttributes<HTMLDivElement> {}

const DialogHeader = React.forwardRef<HTMLDivElement, DialogHeaderProps>(
  ({ className, children, ...props }, ref) => {
    return (
      <div ref={ref} className={cn("mb-5 flex flex-col gap-1.5 text-left", className)} {...props}>
        {children}
      </div>
    );
  }
);
DialogHeader.displayName = "DialogHeader";

export interface DialogTitleProps extends React.HTMLAttributes<HTMLHeadingElement> {}

const DialogTitle = React.forwardRef<HTMLHeadingElement, DialogTitleProps>(
  ({ className, children, ...props }, ref) => {
    const context = React.useContext(DialogContext);

    return (
      <h2
        ref={ref}
        className={cn(
          "text-foreground flex items-center gap-2 text-lg font-bold tracking-tight",
          context.severity === "danger" && "text-destructive",
          className
        )}
        {...props}
      >
        {children}
      </h2>
    );
  }
);
DialogTitle.displayName = "DialogTitle";

export interface DialogDescriptionProps extends React.HTMLAttributes<HTMLParagraphElement> {}

const DialogDescription = React.forwardRef<HTMLParagraphElement, DialogDescriptionProps>(
  ({ className, children, ...props }, ref) => {
    return (
      <p
        ref={ref}
        className={cn("text-muted-foreground text-sm leading-normal", className)}
        {...props}
      >
        {children}
      </p>
    );
  }
);
DialogDescription.displayName = "DialogDescription";

export interface DialogFooterProps extends React.HTMLAttributes<HTMLDivElement> {}

const DialogFooter = React.forwardRef<HTMLDivElement, DialogFooterProps>(
  ({ className, children, ...props }, ref) => {
    return (
      <div
        ref={ref}
        className={cn(
          "mt-2 flex flex-col-reverse gap-2.5 pt-4 sm:flex-row sm:justify-end",
          className
        )}
        {...props}
      >
        {children}
      </div>
    );
  }
);
DialogFooter.displayName = "DialogFooter";

export {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
  dialogPanelVariants,
};

// packages/core/src/components/Divider/Divider.tsx
"use client";
import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../utils/cn";

export type DividerOrientation = "horizontal" | "vertical";
export type DividerVariant = "solid" | "dashed";
export type DividerContentPosition = "left" | "center" | "right";

const dividerVariants = cva("shrink-0", {
  variants: {
    orientation: {
      horizontal: "w-full",
      vertical: "h-full min-h-[1.25rem] w-[1px] self-stretch",
    },
    variant: {
      solid: "",
      dashed: "",
    },
  },
  defaultVariants: {
    orientation: "horizontal",
    variant: "solid",
  },
});

export interface DividerProps
  extends React.HTMLAttributes<HTMLDivElement>, VariantProps<typeof dividerVariants> {
  orientation?: DividerOrientation;
  variant?: DividerVariant;
  contentPosition?: DividerContentPosition;
  children?: React.ReactNode;
}

const Divider = React.forwardRef<HTMLDivElement, DividerProps>(
  (
    {
      className,
      orientation = "horizontal",
      variant = "solid",
      contentPosition = "center",
      children,
      ...props
    },
    ref
  ) => {
    // If divider has children/content (only applicable in horizontal layout)
    if (children && orientation === "horizontal") {
      const isLeft = contentPosition === "left";
      const isRight = contentPosition === "right";

      const lineStyle =
        variant === "dashed"
          ? "border-b border-dashed border-zinc-200 dark:border-zinc-800"
          : "h-[1px] bg-zinc-200/70 dark:bg-zinc-800/70";

      return (
        <div
          ref={ref}
          role="separator"
          aria-orientation="horizontal"
          className={cn("my-3 flex w-full items-center select-none", className)}
          {...props}
        >
          {/* Left line */}
          <div className={cn(lineStyle, isLeft ? "w-8 shrink-0" : isRight ? "flex-1" : "flex-1")} />

          {/* Content */}
          <span className="shrink-0 px-3 text-xs font-medium tracking-wider text-zinc-400 uppercase dark:text-zinc-500">
            {children}
          </span>

          {/* Right line */}
          <div className={cn(lineStyle, isRight ? "w-8 shrink-0" : isLeft ? "flex-1" : "flex-1")} />
        </div>
      );
    }

    // Standard simple divider
    if (orientation === "vertical") {
      return (
        <div
          ref={ref}
          role="separator"
          aria-orientation="vertical"
          className={cn(
            dividerVariants({ orientation, variant }),
            variant === "dashed"
              ? "border-l border-dashed border-zinc-200 bg-transparent dark:border-zinc-800"
              : "bg-zinc-200/70 dark:bg-zinc-800/70",
            className
          )}
          {...props}
        />
      );
    }

    return (
      <div
        ref={ref}
        role="separator"
        aria-orientation="horizontal"
        className={cn(
          dividerVariants({ orientation, variant }),
          variant === "dashed"
            ? "my-3 h-0 border-b border-dashed border-zinc-200 bg-transparent dark:border-zinc-800"
            : "my-3 h-[1px] bg-zinc-200/70 dark:bg-zinc-800/70",
          className
        )}
        {...props}
      />
    );
  }
);

Divider.displayName = "Divider";

export { Divider, dividerVariants };

// packages/core/src/components/Dropdown/Dropdown.tsx
"use client";
import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../utils/cn";

export type DropdownPlacement =
  | "top"
  | "top-start"
  | "top-end"
  | "bottom"
  | "bottom-start"
  | "bottom-end"
  | "left"
  | "left-start"
  | "left-end"
  | "right"
  | "right-start"
  | "right-end"
  | "center";

interface DropdownContextValue {
  isOpen: boolean;
  setIsOpen: React.Dispatch<React.SetStateAction<boolean>>;
  close: () => void;
  placement: DropdownPlacement;
}

const DropdownContext = React.createContext<DropdownContextValue>({
  isOpen: false,
  setIsOpen: () => {},
  close: () => {},
  placement: "bottom-start",
});

export interface DropdownProps extends React.HTMLAttributes<HTMLDivElement> {
  placement?: DropdownPlacement;
  isOpen?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (isOpen: boolean) => void;
  children: React.ReactNode;
}

const Dropdown = React.forwardRef<HTMLDivElement, DropdownProps>(
  (
    {
      className,
      placement = "bottom-start",
      isOpen: propIsOpen,
      defaultOpen = false,
      onOpenChange,
      children,
      ...props
    },
    ref
  ) => {
    const [uncontrolledOpen, setUncontrolledOpen] = React.useState(defaultOpen);
    const containerRef = React.useRef<HTMLDivElement | null>(null);

    const isControlled = propIsOpen !== undefined;
    const isOpen = isControlled ? propIsOpen : uncontrolledOpen;

    const handleSetIsOpen = React.useCallback(
      (valueOrUpdater: boolean | ((prevState: boolean) => boolean)) => {
        const nextValue =
          typeof valueOrUpdater === "function" ? valueOrUpdater(isOpen) : valueOrUpdater;

        if (!isControlled) {
          setUncontrolledOpen(nextValue);
        }
        onOpenChange?.(nextValue);
      },
      [isControlled, isOpen, onOpenChange]
    );

    const close = React.useCallback(() => {
      handleSetIsOpen(false);
    }, [handleSetIsOpen]);

    // Handle outside click
    React.useEffect(() => {
      const handleOutsideClick = (event: MouseEvent) => {
        if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
          close();
        }
      };

      if (isOpen) {
        document.addEventListener("mousedown", handleOutsideClick);
      }
      return () => {
        document.removeEventListener("mousedown", handleOutsideClick);
      };
    }, [isOpen, close]);

    // Handle Escape key
    React.useEffect(() => {
      const handleKeyDown = (e: KeyboardEvent) => {
        if (e.key === "Escape" && isOpen) {
          close();
        }
      };

      if (isOpen) {
        document.addEventListener("keydown", handleKeyDown);
      }
      return () => {
        document.removeEventListener("keydown", handleKeyDown);
      };
    }, [isOpen, close]);

    return (
      <DropdownContext.Provider
        value={{
          isOpen,
          setIsOpen: handleSetIsOpen,
          close,
          placement,
        }}
      >
        <div
          ref={(node) => {
            containerRef.current = node;
            if (typeof ref === "function") ref(node);
            else if (ref) (ref as React.MutableRefObject<HTMLDivElement | null>).current = node;
          }}
          className={cn("relative inline-block text-left", className)}
          {...props}
        >
          {children}
        </div>
      </DropdownContext.Provider>
    );
  }
);
Dropdown.displayName = "Dropdown";

export interface DropdownTriggerProps extends React.HTMLAttributes<HTMLDivElement> {
  children: React.ReactNode;
}

const DropdownTrigger = React.forwardRef<HTMLDivElement, DropdownTriggerProps>(
  ({ className, children, onClick, ...props }, ref) => {
    const { isOpen, setIsOpen } = React.useContext(DropdownContext);

    return (
      <div
        ref={ref}
        className={cn("inline-flex cursor-pointer items-center select-none", className)}
        onClick={(e) => {
          onClick?.(e);
          setIsOpen((prev) => !prev);
        }}
        aria-haspopup="menu"
        aria-expanded={isOpen}
        {...props}
      >
        {children}
      </div>
    );
  }
);
DropdownTrigger.displayName = "DropdownTrigger";

export interface DropdownMenuProps extends React.HTMLAttributes<HTMLDivElement> {
  children: React.ReactNode;
}

const DropdownMenu = React.forwardRef<HTMLDivElement, DropdownMenuProps>(
  ({ className, children, ...props }, ref) => {
    const { isOpen, placement } = React.useContext(DropdownContext);

    if (!isOpen) return null;

    const placementClasses: Record<DropdownPlacement, string> = {
      // Bottom variants (snug 1.5/2 margin right underneath trigger)
      bottom: "top-full left-1/2 -translate-x-1/2 mt-1.5",
      "bottom-start": "top-full left-0 mt-1.5",
      "bottom-end": "top-full right-0 mt-1.5",

      // Top variants (snug right above trigger)
      top: "bottom-full left-1/2 -translate-x-1/2 mb-1.5",
      "top-start": "bottom-full left-0 mb-1.5",
      "top-end": "bottom-full right-0 mb-1.5",

      // Left variants (to the left of trigger)
      left: "right-full top-1/2 -translate-y-1/2 mr-1.5",
      "left-start": "right-full top-0 mr-1.5",
      "left-end": "right-full bottom-0 mr-1.5",

      // Right variants (to the right of trigger)
      right: "left-full top-1/2 -translate-y-1/2 ml-1.5",
      "right-start": "left-full top-0 ml-1.5",
      "right-end": "left-full bottom-0 ml-1.5",

      // Center (centered directly over trigger)
      center: "top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2",
    };

    return (
      <div
        ref={ref}
        role="menu"
        tabIndex={-1}
        className={cn(
          "border-border/80 bg-popover text-popover-foreground absolute z-50 min-w-[210px] rounded-2xl border p-1.5 shadow-xl backdrop-blur-md",
          "animate-in fade-in-0 zoom-in-95 duration-150 focus:outline-none",
          placementClasses[placement] || placementClasses["bottom-start"],
          className
        )}
        {...props}
      >
        <div className="flex flex-col gap-0.5">{children}</div>
      </div>
    );
  }
);
DropdownMenu.displayName = "DropdownMenu";

const dropdownItemVariants = cva(
  "relative flex items-center justify-between w-full px-3 py-2 text-sm rounded-xl cursor-pointer select-none transition-all duration-150 outline-none disabled:pointer-events-none disabled:opacity-50",
  {
    variants: {
      variant: {
        default: "text-popover-foreground hover:bg-accent focus:bg-accent",
        danger: "text-destructive hover:bg-destructive/10 focus:bg-destructive/10 font-medium",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  }
);

export interface DropdownItemProps
  extends React.HTMLAttributes<HTMLDivElement>, VariantProps<typeof dropdownItemVariants> {
  startContent?: React.ReactNode;
  endContent?: React.ReactNode;
  disabled?: boolean;
}

const DropdownItem = React.forwardRef<HTMLDivElement, DropdownItemProps>(
  (
    {
      className,
      variant = "default",
      startContent,
      endContent,
      disabled = false,
      onClick,
      children,
      ...props
    },
    ref
  ) => {
    const { close } = React.useContext(DropdownContext);

    const handleClick = (e: React.MouseEvent<HTMLDivElement>) => {
      if (disabled) return;
      onClick?.(e);
      close();
    };

    return (
      <div
        ref={ref}
        role="menuitem"
        aria-disabled={disabled}
        className={cn(
          dropdownItemVariants({ variant }),
          disabled && "pointer-events-none cursor-not-allowed opacity-40",
          className
        )}
        onClick={handleClick}
        {...props}
      >
        <div className="flex min-w-0 items-center gap-2.5 truncate">
          {startContent && <span className="text-muted-foreground shrink-0">{startContent}</span>}
          <span className="truncate">{children}</span>
        </div>

        {endContent && (
          <span className="text-muted-foreground ml-auto shrink-0 pl-2 font-mono text-xs">
            {endContent}
          </span>
        )}
      </div>
    );
  }
);
DropdownItem.displayName = "DropdownItem";

export interface DropdownSectionProps extends React.HTMLAttributes<HTMLDivElement> {
  title?: string;
  showDivider?: boolean;
}

const DropdownSection = React.forwardRef<HTMLDivElement, DropdownSectionProps>(
  ({ className, title, showDivider = false, children, ...props }, ref) => {
    return (
      <div
        ref={ref}
        role="group"
        className={cn(
          "flex flex-col gap-0.5 py-1",
          showDivider && "border-border/60 mt-1 border-t pt-1.5",
          className
        )}
        {...props}
      >
        {title && (
          <div className="text-muted-foreground px-3 py-1 text-[10px] font-bold tracking-wider uppercase select-none">
            {title}
          </div>
        )}
        {children}
      </div>
    );
  }
);
DropdownSection.displayName = "DropdownSection";

export {
  Dropdown,
  DropdownTrigger,
  DropdownMenu,
  DropdownItem,
  DropdownSection,
  dropdownItemVariants,
};

