// packages/core/src/components/Heading/Heading.tsx
"use client";
import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../utils/cn";

export type HeadingLevel = "h1" | "h2" | "h3" | "h4" | "h5" | "h6";
export type HeadingSize = "h1" | "h2" | "h3" | "h4" | "h5" | "h6" | "inherit";
export type HeadingTracking = "tighter" | "tight" | "normal" | "wide";
export type HeadingColor = "default" | "muted" | "primary";

const headingVariants = cva("font-display transition-colors duration-150 leading-tight", {
  variants: {
    size: {
      h1: "text-4xl font-extrabold md:text-5xl",
      h2: "text-3xl font-bold",
      h3: "text-2xl font-bold",
      h4: "text-xl font-semibold",
      h5: "text-lg font-semibold",
      h6: "text-base font-medium",
      inherit: "text-inherit font-inherit",
    },
    tracking: {
      tighter: "tracking-tighter",
      tight: "tracking-tight",
      normal: "tracking-normal",
      wide: "tracking-wide",
    },
    color: {
      default: "text-zinc-900 dark:text-zinc-50",
      muted: "text-zinc-500 dark:text-zinc-400",
      primary: "text-primary",
    },
    withDivider: {
      true: "pb-3 border-b border-zinc-200/80 dark:border-zinc-800/80 mb-4",
      false: "",
    },
  },
  defaultVariants: {
    size: "h1",
    tracking: "tight",
    color: "default",
    withDivider: false,
  },
});

export interface HeadingProps
  extends React.HTMLAttributes<HTMLHeadingElement>, VariantProps<typeof headingVariants> {
  as?: HeadingLevel;
  size?: HeadingSize;
  tracking?: HeadingTracking;
  color?: HeadingColor;
  withDivider?: boolean;
  children: React.ReactNode;
}

const Heading = React.forwardRef<HTMLHeadingElement, HeadingProps>(
  (
    {
      as: Component = "h1",
      size,
      tracking,
      color = "default",
      withDivider = false,
      className,
      children,
      ...props
    },
    ref
  ) => {
    // Resolve size default to match the semantic tag if size is omitted
    const resolvedSize = size ?? Component;

    // Automatic default optical tracking based on size
    const defaultTrackingForSize: HeadingTracking =
      resolvedSize === "h1" || resolvedSize === "h2"
        ? "tight"
        : resolvedSize === "h3" || resolvedSize === "h4"
          ? "tight"
          : "normal";

    const resolvedTracking = tracking ?? defaultTrackingForSize;

    return (
      <Component
        ref={ref}
        className={cn(
          headingVariants({
            size: resolvedSize,
            tracking: resolvedTracking,
            color,
            withDivider,
          }),
          className
        )}
        {...props}
      >
        {children}
      </Component>
    );
  }
);
Heading.displayName = "Heading";

export { Heading, headingVariants };

// packages/core/src/components/InfiniteScroll/InfiniteScroll.tsx
"use client";
import * as React from "react";
import { cn } from "../utils/cn";

export interface InfiniteScrollProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Content / children elements rendered inside the scrollable container.
   */
  children: React.ReactNode;
  /**
   * Callback invoked when the bottom detector sentinel enters viewport to fetch additional data.
   */
  next: () => void | Promise<void>;
  /**
   * Whether more data items are available to fetch.
   */
  hasMore: boolean;
  /**
   * Visual loading element displayed when loading more items.
   */
  loader?: React.ReactNode;
  /**
   * Optional message or node rendered when all data has been loaded (`hasMore === false`).
   */
  endMessage?: React.ReactNode;
  /**
   * Margin around the root sentinel element for triggering `next` earlier (e.g., '150px').
   * @default "100px"
   */
  rootMargin?: string;
  /**
   * IntersectionObserver threshold (0 to 1).
   * @default 0.1
   */
  threshold?: number;
  /**
   * Whether fetching is currently in flight to prevent duplicate calls.
   */
  isLoading?: boolean;
}

/**
 * InfiniteScroll Component
 * Modern, intersection-observer powered endless scroll container with automatic trigger detection.
 */
export const InfiniteScroll = React.forwardRef<HTMLDivElement, InfiniteScrollProps>(
  (
    {
      children,
      next,
      hasMore,
      loader,
      endMessage,
      rootMargin = "100px",
      threshold = 0.1,
      isLoading = false,
      className,
      ...props
    },
    ref
  ) => {
    const sentinelRef = React.useRef<HTMLDivElement | null>(null);
    const isFetchingRef = React.useRef(false);

    // Keep ref in sync with prop to prevent stale closures
    const nextRef = React.useRef(next);
    nextRef.current = next;

    React.useEffect(() => {
      isFetchingRef.current = isLoading;
    }, [isLoading]);

    React.useEffect(() => {
      const sentinel = sentinelRef.current;
      if (!sentinel || !hasMore) return;

      const observer = new IntersectionObserver(
        (entries) => {
          const target = entries[0];
          if (target && target.isIntersecting && hasMore && !isFetchingRef.current) {
            isFetchingRef.current = true;
            try {
              const res = nextRef.current();
              if (res instanceof Promise) {
                res.finally(() => {
                  isFetchingRef.current = false;
                });
              } else {
                // Micro-debounce for synchronous callbacks
                setTimeout(() => {
                  isFetchingRef.current = false;
                }, 300);
              }
            } catch (err) {
              isFetchingRef.current = false;
              console.error("InfiniteScroll next() error:", err);
            }
          }
        },
        {
          root: null, // viewport or nearest scrollable ancestor
          rootMargin,
          threshold,
        }
      );

      observer.observe(sentinel);

      return () => {
        observer.disconnect();
      };
    }, [hasMore, rootMargin, threshold]);

    return (
      <div ref={ref} className={cn("flex w-full flex-col", className)} {...props}>
        {children}

        {/* Sentinel Detector & Loader / End Indicator */}
        <div ref={sentinelRef} className="flex min-h-[32px] w-full justify-center py-3">
          {hasMore
            ? (loader ?? (
                <div className="flex items-center gap-2 py-2 text-xs font-medium text-zinc-500 dark:text-zinc-400">
                  <svg
                    className="text-primary h-4 w-4 animate-spin"
                    fill="none"
                    viewBox="0 0 24 24"
                  >
                    <circle
                      className="opacity-25"
                      cx="12"
                      cy="12"
                      r="10"
                      stroke="currentColor"
                      strokeWidth="4"
                    />
                    <path
                      className="opacity-75"
                      fill="currentColor"
                      d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                    />
                  </svg>
                  <span>Loading more items...</span>
                </div>
              ))
            : (endMessage ?? (
                <div className="py-2 text-center text-xs font-medium text-zinc-400 dark:text-zinc-600">
                  You have reached the end of the list.
                </div>
              ))}
        </div>
      </div>
    );
  }
);

InfiniteScroll.displayName = "InfiniteScroll";

// packages/core/src/components/Input/Input.tsx
"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../utils/cn";

export type InputVariant = "flat" | "bordered" | "underlined";
export type InputSize = "sm" | "md" | "lg";
export type InputRadius = "none" | "md" | "lg" | "full";
export type InputLabelPlacement = "outside" | "inside";

const inputWrapperVariants = cva(
  "group relative flex items-center w-full transition-all duration-150 text-foreground outline-none select-none",
  {
    variants: {
      variant: {
        flat: "bg-muted hover:bg-muted/80 focus-within:bg-background border border-transparent focus-within:border-ring focus-within:ring-2 focus-within:ring-ring/20 shadow-2xs",
        bordered:
          "bg-transparent border border-border hover:border-foreground/30 focus-within:border-ring focus-within:ring-2 focus-within:ring-ring/20 shadow-2xs",
        underlined:
          "bg-transparent rounded-none border-0 border-b-2 border-border hover:border-foreground/30 focus-within:border-ring px-0.5",
      },
      size: {
        sm: "min-h-8 text-xs px-2.5 gap-1.5",
        md: "min-h-10 text-sm px-3 gap-2",
        lg: "min-h-12 text-base px-3.5 gap-2.5",
      },
      radius: {
        none: "rounded-none",
        md: "rounded-xl",
        lg: "rounded-2xl",
        full: "rounded-full",
      },
      isInvalid: {
        true: "!border-destructive focus-within:!border-destructive focus-within:!ring-destructive/20",
        false: "",
      },
      isDisabled: {
        true: "opacity-50 pointer-events-none select-none cursor-not-allowed",
        false: "",
      },
      labelPlacement: {
        outside: "",
        inside: "items-stretch",
      },
    },
    compoundVariants: [
      {
        variant: "underlined",
        className: "rounded-none",
      },
      {
        labelPlacement: "inside",
        size: "sm",
        className: "min-h-12 py-1 px-3",
      },
      {
        labelPlacement: "inside",
        size: "md",
        className: "min-h-14 py-1.5 px-3.5",
      },
      {
        labelPlacement: "inside",
        size: "lg",
        className: "min-h-16 py-2 px-4",
      },
    ],
    defaultVariants: {
      variant: "flat",
      size: "md",
      radius: "md",
      isInvalid: false,
      isDisabled: false,
      labelPlacement: "outside",
    },
  }
);

export interface InputProps
  extends
    Omit<React.InputHTMLAttributes<HTMLInputElement>, "size">,
    VariantProps<typeof inputWrapperVariants> {
  variant?: InputVariant;
  size?: InputSize;
  /** Backward-compatibility alias for size */
  inputSize?: InputSize;
  radius?: InputRadius;
  label?: React.ReactNode;
  labelPlacement?: InputLabelPlacement;
  isInvalid?: boolean;
  description?: React.ReactNode;
  errorMessage?: React.ReactNode;
  startContent?: React.ReactNode;
  endContent?: React.ReactNode;
  isClearable?: boolean;
  onClear?: () => void;
}

const Input = React.forwardRef<HTMLInputElement, InputProps>(
  (
    {
      className,
      variant = "flat",
      size = "md",
      inputSize,
      radius = "md",
      label,
      labelPlacement = "outside",
      isInvalid = false,
      disabled = false,
      description,
      errorMessage,
      startContent,
      endContent,
      isClearable = false,
      onClear,
      value,
      defaultValue,
      onChange,
      type = "text",
      ...props
    },
    ref
  ) => {
    // Support inputSize alias for seamless backwards-compatibility
    const resolvedSize = inputSize ?? size ?? "md";

    const innerInputRef = React.useRef<HTMLInputElement | null>(null);

    // Merge internal and external refs
    React.useImperativeHandle(ref, () => innerInputRef.current as HTMLInputElement);

    const [uncontrolledVal, setUncontrolledVal] = React.useState<string>(() => {
      if (defaultValue !== undefined) return String(defaultValue);
      return "";
    });

    const isControlled = value !== undefined;
    const currentVal = isControlled ? String(value ?? "") : uncontrolledVal;
    const hasValue = Boolean(currentVal && currentVal.length > 0);

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (!isControlled) {
        setUncontrolledVal(e.target.value);
      }
      onChange?.(e);
    };

    const handleClearClick = (e: React.MouseEvent<HTMLButtonElement>) => {
      e.preventDefault();
      e.stopPropagation();

      if (!isControlled) {
        setUncontrolledVal("");
      }

      if (innerInputRef.current) {
        innerInputRef.current.value = "";
        // Dispatch synthetic change event to trigger reactive form subscribers
        const event = new Event("input", { bubbles: true });
        innerInputRef.current.dispatchEvent(event);
      }

      onClear?.();
      innerInputRef.current?.focus();
    };

    const isInsideLabel = labelPlacement === "inside" && Boolean(label);

    return (
      <div className={cn("flex w-full flex-col text-left", className)}>
        {/* Outside Label */}
        {label && labelPlacement === "outside" && (
          <label
            className={cn(
              "mb-1.5 text-xs font-semibold transition-colors select-none",
              isInvalid ? "text-destructive" : "text-foreground",
              disabled && "cursor-not-allowed opacity-50"
            )}
          >
            {label}
          </label>
        )}

        {/* Input Interactive Box Container */}
        <div
          className={cn(
            inputWrapperVariants({
              variant,
              size: resolvedSize,
              radius,
              isInvalid,
              isDisabled: disabled,
              labelPlacement,
            })
          )}
          onClick={() => innerInputRef.current?.focus()}
        >
          {/* Start Content Slot */}
          {startContent && (
            <div className="text-muted-foreground flex shrink-0 items-center justify-center select-none">
              {startContent}
            </div>
          )}

          {/* Main Input Element or Inside Label Wrapper */}
          {isInsideLabel ? (
            <div className="flex h-full min-w-0 flex-1 flex-col justify-center py-0.5">
              <span
                className={cn(
                  "text-[10px] leading-tight font-semibold tracking-wide uppercase transition-colors select-none",
                  isInvalid ? "text-destructive" : "text-muted-foreground"
                )}
              >
                {label}
              </span>
              <input
                ref={innerInputRef}
                type={type}
                value={isControlled ? value : uncontrolledVal}
                onChange={handleInputChange}
                disabled={disabled}
                aria-invalid={isInvalid ? "true" : undefined}
                className="text-foreground placeholder:text-muted-foreground w-full border-none bg-transparent p-0 leading-tight font-normal outline-none disabled:cursor-not-allowed"
                {...props}
              />
            </div>
          ) : (
            <input
              ref={innerInputRef}
              type={type}
              value={isControlled ? value : uncontrolledVal}
              onChange={handleInputChange}
              disabled={disabled}
              aria-invalid={isInvalid ? "true" : undefined}
              className="text-foreground placeholder:text-muted-foreground h-full w-full border-none bg-transparent font-normal outline-none disabled:cursor-not-allowed"
              {...props}
            />
          )}

          {/* Interactive Clear Button */}
          {isClearable && hasValue && !disabled && (
            <button
              type="button"
              aria-label="Clear input value"
              tabIndex={-1}
              onClick={handleClearClick}
              className="text-muted-foreground hover:bg-muted-foreground/10 hover:text-foreground shrink-0 cursor-pointer rounded-lg p-1 transition-all active:scale-90"
            >
              <svg
                className="h-3.5 w-3.5"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth={2.5}
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                <line x1="18" y1="6" x2="6" y2="18" />
                <line x1="6" y1="6" x2="18" y2="18" />
              </svg>
            </button>
          )}

          {/* End Content Slot */}
          {endContent && (
            <div className="text-muted-foreground flex shrink-0 items-center justify-center select-none">
              {endContent}
            </div>
          )}
        </div>

        {/* Validation Error Message or Helper Description */}
        {isInvalid && errorMessage ? (
          <p
            role="alert"
            className="animate-in fade-in-0 slide-in-from-top-0.5 text-destructive mt-1.5 flex items-center gap-1 text-xs font-medium duration-150"
          >
            {errorMessage}
          </p>
        ) : description ? (
          <p className="text-muted-foreground mt-1.5 text-xs">{description}</p>
        ) : null}
      </div>
    );
  }
);

Input.displayName = "Input";

export { Input, inputWrapperVariants };

// packages/core/src/components/Navbar/Navbar.tsx
"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { motion, AnimatePresence } from "framer-motion";
import { cn } from "../utils/cn";

export type NavbarLayout = "standard" | "admin";
export type NavbarPosition = "static" | "sticky" | "fixed";
export type NavbarMaxWidth = "sm" | "md" | "lg" | "xl" | "2xl" | "full";
export type NavbarLogoPosition = "left" | "center" | "right";
export type NavbarStyleVariant = "glassmorphism" | "transparent" | "floating-full";
export type NavbarMobileMenuVariant = "top" | "left" | "right" | "fullscreen";

interface NavbarContextValue {
  isMenuOpen: boolean;
  setIsMenuOpen: (isOpen: boolean | ((prev: boolean) => boolean)) => void;
  layout: NavbarLayout;
  logoPosition: NavbarLogoPosition;
  styleVariant: NavbarStyleVariant;
  mobileMenuVariant: NavbarMobileMenuVariant;
  isContained: boolean;
  isBordered: boolean;
  isBlurred: boolean;
}

const NavbarContext = React.createContext<NavbarContextValue | undefined>(undefined);

export function useNavbarContext() {
  const context = React.useContext(NavbarContext);
  if (!context) {
    throw new Error("Navbar sub-components must be rendered within a <Navbar> provider.");
  }
  return context;
}

const navbarVariants = cva("w-full transition-all duration-200 box-border", {
  variants: {
    position: {
      static: "relative z-40",
      sticky: "sticky top-0 z-40",
      fixed: "fixed top-0 left-0 right-0 z-40",
    },
    styleVariant: {
      glassmorphism:
        "bg-white/90 dark:bg-zinc-950/90 backdrop-blur-md backdrop-saturate-150 border-b border-zinc-200/80 dark:border-zinc-800/80",
      transparent: "bg-transparent border-b border-transparent shadow-none",
      "floating-full":
        "mt-2 sm:mt-4 mx-auto max-w-5xl rounded-full border border-zinc-200/90 dark:border-zinc-800/90 bg-white/95 dark:bg-zinc-900/95 backdrop-blur-md shadow-lg shadow-zinc-950/5 dark:shadow-black/40 px-3 sm:px-6 transition-all",
    },
    isBordered: {
      true: "",
      false: "border-transparent dark:border-transparent",
    },
    isBlurred: {
      true: "",
      false: "backdrop-blur-none bg-white dark:bg-zinc-950",
    },
  },
  defaultVariants: {
    position: "sticky",
    styleVariant: "glassmorphism",
    isBordered: true,
    isBlurred: true,
  },
});

const containerMaxWidths: Record<NavbarMaxWidth, string> = {
  sm: "max-w-screen-sm",
  md: "max-w-screen-md",
  lg: "max-w-screen-lg",
  xl: "max-w-screen-xl",
  "2xl": "max-w-screen-2xl",
  full: "max-w-full",
};

export interface NavbarProps
  extends React.HTMLAttributes<HTMLElement>, VariantProps<typeof navbarVariants> {
  layout?: NavbarLayout;
  logoPosition?: NavbarLogoPosition;
  styleVariant?: NavbarStyleVariant;
  mobileMenuVariant?: NavbarMobileMenuVariant;
  position?: NavbarPosition;
  isBordered?: boolean;
  isBlurred?: boolean;
  maxWidth?: NavbarMaxWidth;
  isMenuOpen?: boolean;
  onMenuOpenChange?: (isOpen: boolean) => void;
  isMenuDefaultOpen?: boolean;
  isContained?: boolean;
  lockScroll?: boolean;
}

const Navbar = React.forwardRef<HTMLElement, NavbarProps>(
  (
    {
      className,
      layout = "standard",
      logoPosition = "left",
      styleVariant = "glassmorphism",
      mobileMenuVariant = "top",
      position = "sticky",
      isBordered = true,
      isBlurred = true,
      maxWidth = "full",
      isMenuOpen: controlledIsMenuOpen,
      onMenuOpenChange,
      isMenuDefaultOpen = false,
      isContained = false,
      lockScroll = true,
      children,
      ...props
    },
    ref
  ) => {
    const internalRef = React.useRef<HTMLElement>(null);
    const mergedRef = React.useMemo(() => {
      if (typeof ref === "function") {
        return (node: HTMLElement | null) => {
          ref(node);
          internalRef.current = node;
        };
      } else if (ref) {
        return (node: HTMLElement | null) => {
          (ref as React.MutableRefObject<HTMLElement | null>).current = node;
          internalRef.current = node;
        };
      }
      return internalRef;
    }, [ref]);

    const [uncontrolledIsMenuOpen, setUncontrolledIsMenuOpen] =
      React.useState<boolean>(isMenuDefaultOpen);

    const isControlled = controlledIsMenuOpen !== undefined;
    const isMenuOpen = isControlled ? controlledIsMenuOpen : uncontrolledIsMenuOpen;

    const setIsMenuOpen = React.useCallback(
      (value: boolean | ((prev: boolean) => boolean)) => {
        const nextValue = typeof value === "function" ? value(isMenuOpen) : value;
        if (!isControlled) {
          setUncontrolledIsMenuOpen(nextValue);
        }
        onMenuOpenChange?.(nextValue);
      },
      [isControlled, isMenuOpen, onMenuOpenChange]
    );

    // Prevent body-scroll leak when mobile drawer is open in full viewport mode
    React.useEffect(() => {
      // Find the correct document context in case we are rendered in an iframe portal
      const currentDocument =
        (typeof window !== "undefined" && internalRef.current?.ownerDocument) ||
        (typeof document !== "undefined" ? document : null);

      if (isMenuOpen && lockScroll && !isContained && currentDocument) {
        const docBody = currentDocument.body;
        const originalOverflow = docBody.style.overflow;
        const originalPaddingRight = docBody.style.paddingRight;
        const currentWindow = currentDocument.defaultView || window;
        const scrollbarWidth = currentWindow
          ? currentWindow.innerWidth - currentDocument.documentElement.clientWidth
          : 0;

        docBody.style.overflow = "hidden";
        if (scrollbarWidth > 0) {
          docBody.style.paddingRight = `${scrollbarWidth}px`;
        }

        return () => {
          docBody.style.overflow = originalOverflow;
          docBody.style.paddingRight = originalPaddingRight;
        };
      }
    }, [isMenuOpen, lockScroll, isContained, internalRef.current]);

    const contextValue = React.useMemo(
      () => ({
        isMenuOpen,
        setIsMenuOpen,
        layout,
        logoPosition,
        styleVariant,
        mobileMenuVariant,
        isContained,
        isBordered,
        isBlurred,
      }),
      [
        isMenuOpen,
        setIsMenuOpen,
        layout,
        logoPosition,
        styleVariant,
        mobileMenuVariant,
        isContained,
        isBordered,
        isBlurred,
      ]
    );

    const isFloating = styleVariant === "floating-full";

    // Separate NavbarMenu from main header children so drawer overlays are never constrained by the h-16 flex row
    const barChildren: React.ReactNode[] = [];
    const leftRightFullscreenMenuChildren: React.ReactNode[] = [];
    const topMenuChildren: React.ReactNode[] = [];

    React.Children.forEach(children, (child) => {
      if (
        React.isValidElement(child) &&
        ((child.type as any)?.displayName === "NavbarMenu" ||
          (child.type as any)?.__isNavbarMenu ||
          child.type === NavbarMenu ||
          (child.props as any)?.variant !== undefined ||
          (child.props as any)?.isContained !== undefined)
      ) {
        if ((child.props as any)?.variant === "top" || !(child.props as any)?.variant) {
          topMenuChildren.push(child);
        } else {
          leftRightFullscreenMenuChildren.push(child);
        }
      } else {
        barChildren.push(child);
      }
    });

    return (
      <NavbarContext.Provider value={contextValue}>
        <nav
          ref={mergedRef}
          data-logo-position={logoPosition}
          data-style-variant={styleVariant}
          data-mobile-variant={mobileMenuVariant}
          className={cn(
            navbarVariants({
              position,
              styleVariant,
              isBordered,
              isBlurred,
              className,
            }),
            isMenuOpen && "z-50",
            isMenuOpen &&
              styleVariant === "transparent" &&
              "bg-white transition-colors dark:bg-zinc-950",
            isContained && styleVariant !== "floating-full" && "rounded-t-2xl",
            isContained && !isMenuOpen && styleVariant !== "floating-full" && "rounded-b-2xl"
          )}
          {...props}
        >
          <div
            className={cn(
              "mx-auto flex h-16 w-full flex-nowrap items-center justify-between px-4 sm:px-6",
              !isFloating && containerMaxWidths[maxWidth],
              isFloating && "px-3 sm:px-5"
            )}
          >
            {barChildren}
          </div>
          {topMenuChildren}
        </nav>
        {leftRightFullscreenMenuChildren}
      </NavbarContext.Provider>
    );
  }
);
Navbar.displayName = "Navbar";

/* -------------------------------------------------------------------------------------------------
 * NavbarBrand
 * -----------------------------------------------------------------------------------------------*/

export interface NavbarBrandProps extends React.HTMLAttributes<HTMLDivElement> {
  position?: NavbarLogoPosition;
}

const NavbarBrand = React.forwardRef<HTMLDivElement, NavbarBrandProps>(
  ({ className, position: explicitPosition, children, ...props }, ref) => {
    const { logoPosition: contextPosition } = useNavbarContext();
    const logoPosition = explicitPosition || contextPosition;

    const logoPositionClasses: Record<NavbarLogoPosition, string> = {
      left: "justify-start mr-auto shrink-0",
      center: "justify-center mx-auto shrink-0",
      right: "justify-end ml-auto order-last shrink-0",
