 * -----------------------------------------------------------------------------------------------*/

export interface NavbarMenuToggleProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  icon?: React.ReactNode;
  "aria-label"?: string;
  forceVisible?: boolean;
}

const lineSpringTransition = {
  type: "spring" as const,
  stiffness: 350,
  damping: 25,
};

const NavbarMenuToggle = React.forwardRef<HTMLButtonElement, NavbarMenuToggleProps>(
  (
    {
      className,
      icon,
      "aria-label": ariaLabel = "Toggle navigation menu",
      forceVisible = false,
      onClick,
      ...props
    },
    ref
  ) => {
    const { isMenuOpen, setIsMenuOpen } = useNavbarContext();

    const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
      setIsMenuOpen((prev) => !prev);
      onClick?.(e);
    };

    return (
      <button
        ref={ref}
        type="button"
        aria-label={ariaLabel}
        aria-expanded={isMenuOpen}
        onClick={handleClick}
        className={cn(
          forceVisible ? "flex" : "flex md:hidden",
          "relative h-9 w-9 shrink-0 cursor-pointer items-center justify-center rounded-lg border border-zinc-200 bg-white text-zinc-700 shadow-xs transition-all select-none hover:bg-zinc-100 focus-visible:ring-2 focus-visible:ring-indigo-500 focus-visible:ring-offset-2 focus-visible:outline-none active:scale-95 dark:border-zinc-800 dark:bg-zinc-900 dark:text-zinc-200 dark:hover:bg-zinc-800 dark:focus-visible:ring-offset-zinc-950",
          className
        )}
        {...props}
      >
        {icon ? (
          icon
        ) : (
          <div className="relative flex h-4 w-4 flex-col items-center justify-between overflow-hidden">
            {/* Top Line */}
            <motion.span
              animate={
                isMenuOpen ? { rotate: 45, y: 7, width: 16 } : { rotate: 0, y: 0, width: 16 }
              }
              transition={lineSpringTransition}
              className="h-0.5 origin-center rounded-full bg-current"
            />
            {/* Middle Line */}
            <motion.span
              animate={
                isMenuOpen ? { opacity: 0, scaleX: 0 } : { opacity: 1, scaleX: 1, width: 16 }
              }
              transition={{ duration: 0.15 }}
              className="h-0.5 origin-center rounded-full bg-current"
            />
            {/* Bottom Line */}
            <motion.span
              animate={
                isMenuOpen ? { rotate: -45, y: -7, width: 16 } : { rotate: 0, y: 0, width: 16 }
              }
              transition={lineSpringTransition}
              className="h-0.5 origin-center rounded-full bg-current"
            />
          </div>
        )}
      </button>
    );
  }
);
NavbarMenuToggle.displayName = "NavbarMenuToggle";

