          }
        case "flat":
          switch (color) {
            case "primary":
              return "bg-indigo-100 text-indigo-700 dark:bg-indigo-950/60 dark:text-indigo-300 hover:bg-indigo-200 dark:hover:bg-indigo-900/60 focus-visible:ring-indigo-500";
