            classNames?.wrapper
          )}
        >
          <div
            className={cn(
              radioCircleVariants({ size, color, isChecked, isInvalid }),
              classNames?.control
            )}
          >
            <span className={cn(radioDotVariants({ size, color, isChecked }))} />
          </div>
        </div>

        {/* Label and Description */}
        {(label || children || description) && (
          <div
            className={cn(
              "flex flex-col text-left",
              isCard ? "ml-3" : "",
              classNames?.labelWrapper
            )}
          >
            {(label || children) && (
